#version 300 es
precision mediump float;

// 四色型色覚（Tetrachromacy）シミュレーション。
// LMS 変換 + 赤-緑 opponent channel 誇張。
// CPU 実装 vision::tetrachromacy に対応。
//
// メタメリックペア候補領域（|delta| < 0.05）の Cb/Cr 誇張は、
// GPU では閾値判定が難しいため全領域に opponent channel 誇張を適用する簡略版。

uniform sampler2D uTexture;
uniform float uStrength;

in vec2 vTexCoord;
out vec4 fragColor;

float srgbToLinear(float c) {
    return c <= 0.04045 ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4);
}
float linearToSrgb(float c) {
    return c <= 0.0031308 ? c * 12.92 : 1.055 * pow(c, 1.0 / 2.4) - 0.055;
}

void main() {
    vec4 orig = texture(uTexture, vTexCoord);
    float r = srgbToLinear(orig.r);
    float g = srgbToLinear(orig.g);
    float b = srgbToLinear(orig.b);

    // Machado 2009 linear sRGB → LMS 変換行列の第1-2行
    float lCone = 0.4002 * r + 0.7076 * g + (-0.0808) * b;
    float mCone = (-0.2263) * r + 1.1653 * g + 0.0457 * b;

    float delta = mCone - lCone;

    float rg = r - g;
    const float K_RG = 0.5;

    float nr, ng, nb;

    if (abs(delta) < 0.05) {
        // メタメリックペア候補: Cb/Cr 誇張
        float luma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
        float cb = b - luma;
        float cr = r - luma;
        float scale = uStrength * 2.0;
        nr = clamp(luma + cr * scale, 0.0, 1.0);
        ng = clamp(luma, 0.0, 1.0);
        nb = clamp(luma + cb * scale, 0.0, 1.0);
    } else {
        // 全領域: 赤-緑 opponent channel 誇張
        nr = clamp(r + uStrength * rg * K_RG, 0.0, 1.0);
        ng = clamp(g - uStrength * rg * K_RG, 0.0, 1.0);
        nb = b;
    }

    fragColor = vec4(
        linearToSrgb(nr),
        linearToSrgb(ng),
        linearToSrgb(nb),
        orig.a
    );
}

#version 300 es
precision mediump float;

// 等方 disk blur（pillbox kernel）— 近視 / 遠視 / 老眼シミュレーション
// Poisson disk サンプリング（16 サンプル）で円形ぼかしを近似する。

uniform sampler2D uTexture;
uniform float uStrength;
uniform float uRadiusPx;     // ぼかし半径（ピクセル単位）
uniform vec2  uTexelSize;    // vec2(1.0/width, 1.0/height)

in vec2 vTexCoord;
out vec4 fragColor;

float srgbToLinear(float c) {
    return c <= 0.04045 ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4);
}

float linearToSrgb(float c) {
    return c <= 0.0031308 ? c * 12.92 : 1.055 * pow(c, 1.0 / 2.4) - 0.055;
}

// Fibonacci lattice による円形サンプリング（16 点）
vec4 diskBlur(vec2 uv, float radius) {
    if (radius < 0.5) return texture(uTexture, uv);

    const int N = 16;
    // 黄金角 phi ≈ 137.508°
    const float PHI = 2.399963229728653;

    vec3 acc = vec3(0.0);
    float totalWeight = 0.0;

    for (int i = 0; i < N; i++) {
        float t = float(i) / float(N);
        float r = sqrt(t) * radius;
        float theta = float(i) * PHI;
        vec2 offset = vec2(cos(theta), sin(theta)) * r * uTexelSize;
        vec4 s = texture(uTexture, uv + offset);
        // linear 空間でサンプリング
        vec3 lin = vec3(srgbToLinear(s.r), srgbToLinear(s.g), srgbToLinear(s.b));
        acc += lin;
        totalWeight += 1.0;
    }

    vec3 blurred = acc / totalWeight;
    return vec4(
        linearToSrgb(clamp(blurred.r, 0.0, 1.0)),
        linearToSrgb(clamp(blurred.g, 0.0, 1.0)),
        linearToSrgb(clamp(blurred.b, 0.0, 1.0)),
        texture(uTexture, uv).a
    );
}

void main() {
    fragColor = diskBlur(vTexCoord, uRadiusPx);
}

