    const int N = 16;
    const float PHI = 2.399963229728653; // 黄金角 ≈ 137.508°
    vec3 acc = vec3(0.0);
    for (int i = 0; i < N; i++) {
        float t = float(i) / float(N);
        float r = sqrt(t) * radius;
        float theta = float(i) * PHI;
        vec2 offset = vec2(cos(theta), sin(theta)) * r * uTexelSize;
