    fragColor = vec4(
        linearToSrgb(clamp(lin.r + bloom.r, 0.0, 1.0)),
        linearToSrgb(clamp(lin.g + bloom.g, 0.0, 1.0)),
        linearToSrgb(clamp(lin.b + bloom.b, 0.0, 1.0)),
        orig.a
    );
}

